WITH rollup_totals AS (SELECT d.account_type, s.txn_type, COUNT(*) AS rows_total, ROUND(SUM(s.amount), 2) AS total_amount FROM transactions s LEFT JOIN accounts d ON s.account_id = d.id GROUP BY d.account_type, s.txn_type) SELECT account_type, txn_type, rows_total, total_amount, CASE WHEN account_type RLIKE '^(SAVINGS|LOAN)$' THEN 'OTHER_ZONE' WHEN account_type RLIKE '^(CHECKING|CREDIT)$' THEN 'CORE' ELSE 'GROUP_A' END AS account_type_zone FROM rollup_totals ORDER BY total_amount DESC NULLS FIRST;
